import { test, expect } from '@playwright/test';

test.describe('Update Display Name - User Profile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
  });

  test('should successfully update display name and reflect it across the app', async ({ page }) => {
    // Verify initial display name is visible
    const displayNameInput = page.getByLabel('Display Name');
    await expect(displayNameInput).toBeVisible();
    const displayNameValue = await displayNameInput.getByRole('textbox').textContent();
    expect(displayNameValue).toBe('John Doe');

    // Verify current user name is displayed
    const userNameDisplay = page.getByText('John Doe');
    await expect(userNameDisplay).toBeVisible();

    // Update display name using getByLabel
    const newDisplayNameInput = page.getByLabel('Display Name');
    await newDisplayNameInput.fill('Jane Smith');

    // Verify new display name is visible
    const newDisplayNameValue = await newDisplayNameInput.getByRole('textbox').textContent();
    expect(newDisplayNameValue).toBe('Jane Smith');

    // Verify user name is updated
    const updatedUserNameDisplay = page.getByText('Jane Smith');
    await expect(updatedUserNameDisplay).toBeVisible();

    // Verify email is still visible and unchanged
    const emailDisplay = page.getByText('jane.smith@example.com');
    await expect(emailDisplay).toBeVisible();

    // Verify profile picture is still visible
    const profilePicture = page.getByRole('img', { name: /profile picture/i });
    await expect(profilePicture).toBeVisible();

    // Verify navigation menu is still visible
    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    // Verify settings button is still visible
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();

    // Verify user is still logged in
    const userStatus = page.getByText('Logged in');
    await expect(userStatus).toBeVisible();
  });

  test('should handle empty display name input and display error message', async ({ page }) => {
    // Verify initial display name is visible
    const displayNameInput = page.getByLabel('Display Name');
    await expect(displayNameInput).toBeVisible();

    // Verify error message is not visible initially
    const errorMessage = page.getByText(/display name is required/i);
    await expect(errorMessage).not.toBeVisible();

    // Attempt to update with empty input
    const emptyDisplayNameInput = page.getByLabel('Display Name');
    await emptyDisplayNameInput.fill('');

    // Verify error message is now visible
    await expect(errorMessage).toBeVisible();

    // Verify error message contains correct text
    await expect(errorMessage).toContainText(/display name is required/i);

    // Verify update button is still visible
    const updateButton = page.getByRole('button', { name: /update/i });
    await expect(updateButton).toBeVisible();

    // Verify navigation menu is still visible
    const navigationMenu = page.getByRole('navigation');
    await expect(navigationMenu).toBeVisible();

    // Verify user is still logged in
    const userStatus = page.getByText('Logged in');
    await expect(userStatus).toBeVisible();
  });
});
